------------ import ------------
local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
--local RawImageAlterable = CS.Engine.UI.RawImageAlterable
local ImageAlterable = CS.Engine.UI.ImageAlterable
local BG_STATUS = {
    NORMAL = 1, -- 普通
    SELECT = 2, -- 选中
    FINISH = 3, -- 完成
}
local TEXT_STATUS = {
    NORMAL = 1, -- 普通
    SELECT = 2, -- 选中
    LOCKED = 3, -- 锁定
}

---@class BeginnerSevenDayCellNode
---@field CommonRedPoint                	UnityEngine.RectTransform
---@field ImgComplete                   	UnityEngine.RectTransform
---@field TextDay                       	UnityEngine.RectTransform
---@field Lock                          	UnityEngine.RectTransform
---@field UnLock                        	UnityEngine.RectTransform
---@field TxtProgress                   	TMPro.TextMeshProUGUI
---@field TextNumber                    	TMPro.TextMeshProUGUI
---@field ImgBg                         	Game.Native.Common.UISwitchImage
---@field BtnDayNode                    	UnityEngine.UI.Button

local BeginnerSevenDayCellNode = Class("BeginnerSevenDayCellNode")
function BeginnerSevenDayCellNode:__init()
    self.btnAction   = nil
    self.maxDay = 0
    self.isComplete = false
    self.drawnFinalPrize = 0
end

function BeginnerSevenDayCellNode:__delete()
    self.btnAction   = nil
    self.controller  = nil
    self.maxDay = 0
end

---SetCallBack
---设置单击回调函数
function BeginnerSevenDayCellNode:SetBtnCallBack(cb)
    self.btnAction = cb
end

function BeginnerSevenDayCellNode:GetCellDt()
    return checkTable(self.cellDt)
end

function BeginnerSevenDayCellNode:GetToday()
    return checkInt(self.curDay)
end

function BeginnerSevenDayCellNode:GetProgress()
    return checkInt(self:GetCellDt().progress)
end

function BeginnerSevenDayCellNode:GetTotal()
    return checkInt(self:GetCellDt().count)
end

function BeginnerSevenDayCellNode:GetDay()
    return checkInt(self:GetCellDt().day)
end


function BeginnerSevenDayCellNode:Awake()
    SetButtonAction(self.controller.gameObject, function ()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end)
end

function BeginnerSevenDayCellNode:FreshBaseUI(data, curDay, isSelected, maxDay, isComplete, drawnFinalPrize, isNew)
    self.cellDt = checkTable(data)
    self.curDay = checkInt(curDay)
    self.maxDay = checkInt(maxDay)
    self.isComplete = checkBool(isComplete)
    self.drawnFinalPrize = checkInt(drawnFinalPrize)
    if self:GetDay() == maxDay then
        ---刷新头像 ui转用的好像
        local rewardsVo = CfUtils.GetWholeVo(AutoIds.IdSetting920, "SevenDaysBigPrizeVo")
        if isNew then
            rewardsVo = CfUtils.GetWholeVo(AutoIds.IdSetting8920, "SevenDaysBigPrizeVo")
        end
        --local length = #rewardsVo
        local curSlideShowCardId = checkInt(rewardsVo[1].reward)
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(curSlideShowCardId)
        if cardVo then
            --KTool.GetOrAddComponent(self.Lock.transform.parent:Find("ImgBg/ImgHead").gameObject, typeof(ImageAlterable))
            -----@type CardSkinVo
            --local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardVo.defaultSkin)
            --CfUtils.FillImage(self.Lock.transform.parent:Find("ImgBg/ImgHead"), skinVo.buffHead)
        end
        ---最后一天的情况下
        if isComplete and checkNumber(drawnFinalPrize) == 0 then
            ---任务完成了 但大奖励没有领取,添加小红点状态
            CfUtils.SetActive(self.CommonRedPoint, true)
        else
            CfUtils.SetActive(self.CommonRedPoint, false)
        end
    end
    CfUtils.FillText(self.TextNumber, self:GetDay())
    CfUtils.FillText(self.TxtProgress, string.format("%s/%s", self:GetProgress(), self:GetTotal()))
    local isLocked        = self:GetToday() < self:GetDay()
    KTool.SetActive(self.Lock.gameObject, isLocked)

    self:FreshSelectStatus(isSelected)
    self:PlayAnimation(isSelected)
end

function BeginnerSevenDayCellNode:FreshSelectStatus(status)
    local isLocked   = self:GetToday() < self:GetDay()
    local isComplete = self:GetProgress() == self:GetTotal()
    local isSelected = checkBool(status)

    CfUtils.SetUISwitchText(self.TextDay, isSelected and TEXT_STATUS.SELECT or TEXT_STATUS.NORMAL)
    CfUtils.SetUISwitchText(self.TxtProgress, isSelected and TEXT_STATUS.SELECT or TEXT_STATUS.NORMAL)
    CfUtils.SetUISwitchText(self.TextNumber, isSelected and TEXT_STATUS.SELECT or (isLocked and TEXT_STATUS.LOCKED or TEXT_STATUS.NORMAL))
    CfUtils.SetUISwitchImage(self.ImgBg, isSelected and BG_STATUS.SELECT or (isComplete and BG_STATUS.FINISH or BG_STATUS.NORMAL))

    KTool.SetActive(self.TxtProgress, isSelected or (not isComplete and not isLocked))
    if self:GetDay() == checkInt(self.maxDay) then
        KTool.SetActive(self.ImgComplete, not isSelected and isComplete and checkInt(self.drawnFinalPrize) == 1)
    else
        KTool.SetActive(self.ImgComplete, not isSelected and isComplete)
    end
    CfUtils.PlayAnimator(self.controller, isSelected and "Now" or "Default")
end

function BeginnerSevenDayCellNode:PlayAnimation(isSelected)
    CfUtils.PlayAnimation(self.controller,isSelected and "BeginnerEventDialog_BtnDaySevenNode_Select" or "BeginnerEventDialog_BtnDaySevenNode_Back")
end

function BeginnerSevenDayCellNode:UpdateRedPointStatus(status)
    local isUnlocked   = self:GetToday() >= self:GetDay()
    KTool.SetActive(self.CommonRedPoint, status and isUnlocked)
end

function BeginnerSevenDayCellNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return BeginnerSevenDayCellNode